'use client';

/**
 * AI Generated Badge Component
 * Displays an indicator that a form/transaction was generated by AI
 */

import React from 'react';
import { Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';

interface AIGeneratedBadgeProps {
  className?: string;
  variant?: 'default' | 'compact';
}

export function AIGeneratedBadge({
  className,
  variant = 'default',
}: AIGeneratedBadgeProps) {
  if (variant === 'compact') {
    return (
      <div
        className={cn(
          'inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-xs font-medium',
          'bg-purple-100 dark:bg-purple-900 text-purple-800 dark:text-purple-200',
          'border border-purple-200 dark:border-purple-800',
          className
        )}
      >
        <Sparkles className="w-3 h-3" />
        <span>AI Generated</span>
      </div>
    );
  }

  return (
    <div
      className={cn(
        'flex items-start gap-3 p-3 rounded-lg border',
        'bg-purple-50 dark:bg-purple-950 border-purple-200 dark:border-purple-800',
        className
      )}
    >
      <div className="flex-shrink-0 mt-0.5">
        <Sparkles className="w-5 h-5 text-purple-600 dark:text-purple-400" />
      </div>
      <div className="flex-1">
        <h4 className="text-sm font-semibold text-purple-900 dark:text-purple-100 mb-1">
          AI-Generated Transaction
        </h4>
        <p className="text-xs text-purple-700 dark:text-purple-300">
          This transaction was created by the AI assistant. Please review the details
          carefully before saving.
        </p>
      </div>
    </div>
  );
}
